declare(strict_types=1);require_once __DIR__.'/includes/registration_schema.php';ensure_registration_schema();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$level=$_GET['level']??'';$fields=['primary'=>['primary_pdf','primary_name'],'lower'=>['lower_pdf','lower_name'],'upper'=>['upper_pdf','upper_name']];if(!$id||!isset($fields[$level])){http_response_code(404);exit('ไม่พบเอกสาร');}[$pathField,$nameField]=$fields[$level];$s=db()->prepare("SELECT {$pathField} AS pdf_url,{$nameField} AS pdf_name FROM registration_plans WHERE id=:id AND status=\"published\"");$s->execute(['id'=>$id]);$r=$s->fetch();if(!$r||!$r['pdf_url']){http_response_code(404);exit('ไม่พบเอกสาร');}$base=realpath(__DIR__.'/uploads/registration');$path=realpath(__DIR__.'/'.ltrim(str_replace('\\','/',$r['pdf_url']),'/'));if(!$base||!$path||!str_starts_with($path,$base)||!is_file($path)){http_response_code(404);exit('ไม่พบไฟล์');}$name=$r['pdf_name']?:basename($path);$disposition=($_GET['download']??'')==='1'?'attachment':'inline';header('Content-Type:application/pdf');header('Content-Length:'.filesize($path));header('Content-Disposition:'.$disposition.'; filename="document.pdf"; filename*=UTF-8\'\''.rawurlencode($name));readfile($path);
